/* Selected A. Tier = a circuit of all four realms; node = a step inside one realm.
   Accelerated, in-memory prototype. Production progression and rewards remain server-owned. */
const RealmProgression=(()=>{
    const J=MageRealms.journey,scenes=['route','gate','fireEnd','windEnd','tier2','revisit'];
    const labels={route:'Tier 1 · Realmväg',gate:'Bossgrind · Nod 13',fireEnd:'Fire → Ice · Tier 1',windEnd:'Wind 1 → Fire 2',tier2:'Tier 2 · Ny loot',revisit:'Återbesök · Tier 1'};
    let data=J.fresh(),review='route';
    const enabled=()=>new URLSearchParams(location.search).get('progression')==='A';
    const inspect=()=>({...structuredClone(data),bossNodes:J.bossNodes,nodeCount:J.nodeCount,gate:J.gate(data),target:J.target(data),review,simulated:true});
    const current=()=>J.place(data.realm,data.node),strength=()=>1+(data.tier-1)*.5,enemyHp=()=>Math.round(40*strength()),atBoss=()=>J.gate(data);
    const complete=(t=data.tier,r=data.realm)=>J.cleared(data,t,r)===J.nodeCount;
    const nextBoss=()=>J.bossNodes.find(n=>n>J.cleared(data))||J.nodeCount;
    const bossName=()=>nextBoss()===J.nodeCount?MageRealms.routes[data.realm].boss.guardian:data.realm===0?({6:'The Ember Watcher',13:'The Cinder Warden',19:'The Ashen Knight'})[nextBoss()]:realms[data.realm]+' '+({6:'Watcher',13:'Warden',19:'Knight'})[nextBoss()];
    const status=()=>complete()?'Realm cleared':data.node!==J.frontier(data)?'Farming cleared ground':atBoss()?'Boss ahead':'Farming';
    function sync(){state.realm=data.realm;state.stageKills=0;state.enemyHp=enemyHp();state.heldLevel=complete()||data.node!==J.frontier(data);for(let r=0;r<4;r++){state.won[r]=complete(1,r);if(state.won[r])state.cleared[r]=state.levels[r]=MageRealms.count(r);}resetIdleAnimation();}
    function seed(tier,realm,node){data=J.fresh();while(J.pairIndex(data.tier,data.realm)<J.pairIndex(tier,realm)){while(!complete()){if(atBoss())J.defeat(data,J.target(data));else J.clearIdle(data);}const n=J.next(data);J.travel(data,n.tier,n.realm,1);}while(J.cleared(data)<node-1){if(atBoss())J.defeat(data,J.target(data));else J.clearIdle(data);}data.node=J.frontier(data);}
    function scenario(key){review=scenes.includes(key)?key:'route';state=fresh();if(review==='fireEnd')seed(1,0,24);else if(review==='windEnd')seed(1,3,24);else if(review==='tier2'||review==='revisit')seed(2,0,1);else seed(1,0,12);if(['gate','fireEnd','windEnd'].includes(review))J.clearIdle(data);if(review==='revisit')J.travel(data,1,0,9);sync();const u=new URL(location.href);u.searchParams.set('progression','A');u.searchParams.set('journey',review);history.replaceState(null,'',u);render();}
    function locationView(){return `<button class="location-plaque progression-plaque progression-A" data-action="map" aria-label="${realms[data.realm]} realm, Tier ${data.tier}, Node ${data.node} of ${J.nodeCount}, ${current().name}. Open realm journey"><span class="tier-sigil">${data.tier}<small>TIER</small></span><span class="progression-copy"><span class="kicker">${realms[data.realm].toUpperCase()} REALM</span><strong>${current().name}</strong><small>Node <b>${data.node}</b> / ${J.nodeCount} · ${status()}</small></span><span class="progression-chevron" aria-hidden="true">⌄</span></button>`;}
    function progress(){return `<div class="place-progress" role="progressbar" aria-label="Nodes cleared in ${realms[data.realm]} realm, Tier ${data.tier}" aria-valuemin="0" aria-valuemax="${J.nodeCount}" aria-valuenow="${J.cleared(data)}"><i style="width:${J.cleared(data)/J.nodeCount*100}%"></i></div>`;}
    const mapState=()=>({tier:state.modal.journeyTier??data.tier,realm:state.modal.journeyRealm??data.realm});
    function nodeMarkup(tier,realm,n){const cleared=J.cleared(data,tier,realm),boss=J.isBoss(n),here=tier===data.tier&&realm===data.realm&&n===data.node,open=J.canVisit(data,tier,realm),ready=boss&&n===cleared+1&&open,allowed=open&&(boss?ready:n<=J.frontier(data,tier,realm));return `<button class="journey-node ${boss?'boss-node':''} ${n<=cleared?'cleared':''} ${here?'here':''} ${ready?'boss-ready':''}" data-journey-node="${n}" style="--node-order:${Math.floor((n-1)/5)*5+(Math.floor((n-1)/5)%2?4-(n-1)%5:(n-1)%5)}" ${allowed?'':'disabled'} ${here?'aria-current="location"':''} aria-label="Node ${n}, ${boss?'boss':'idle'}${here?', farming here':n<=cleared?', cleared':ready?', ready':', locked'}"><span class="node-medallion">${boss?sprite('golem'):''}<b>${n}</b></span>${n<=cleared?'<span class="node-check" aria-hidden="true">✓</span>':''}</button>`;}
    function view(){const{tier,realm}=mapState(),open=J.canVisit(data,tier,realm),cleared=J.cleared(data,tier,realm),same=tier===data.tier&&realm===data.realm,ready=same&&atBoss(),p=J.place(realm,same?data.node:J.frontier(data,tier,realm));return `<div class="tier-journey"><header class="tier-map-heading"><button class="text-button" data-journey-tier="${tier-1}" ${tier===1?'disabled':''} aria-label="View previous tier">←</button><h3>Tier ${tier}</h3><button class="text-button" data-journey-tier="${tier+1}" ${tier>Math.floor(data.unlocked/4)+1?'disabled':''} aria-label="View next tier">→</button><button class="sheet-close" data-action="close" aria-label="Close realm journey">×</button></header><nav class="atlas-tabs tier-realms" aria-label="Realms in this tier">${realms.map((name,r)=>`<button data-journey-realm="${r}" aria-pressed="${r===realm}" aria-label="${name} realm, Tier ${tier}${J.canVisit(data,tier,r)?'':', locked'}">${ui(name.toLowerCase())}<span>${name}</span>${complete(tier,r)?'<b>✓</b>':J.canVisit(data,tier,r)?'':ui('lock','inline-icon')}</button>`).join('')}</nav><div class="journey-position"><strong>${open?p.name:'Unexplored'}</strong><span>${open?cleared+' / '+J.nodeCount+' cleared':ui('lock','inline-icon')+' Locked'}</span></div><div class="journey-grid" role="group" aria-label="${realms[realm]} realm, Tier ${tier}, 25 nodes; bosses at 6, 13, 19 and 25">${Array.from({length:J.nodeCount},(_,i)=>nodeMarkup(tier,realm,i+1)).join('')}</div><div class="journey-map-key"><span><i class="node-dot"></i> Idle</span><span>${sprite('golem')} Boss</span>${tier>1?`<span>${ui('empty','inline-icon')} New loot</span>`:'<span>◆ Current</span>'}</div><div class="journey-footer">${open?`<button class="rune-button ${ready?'':'secondary'}" data-journey-primary="${ready?'boss':'farm'}">${ready?'Challenge boss · '+nextBoss():same&&data.node===J.frontier(data)?'Continue farming':'Farm here'}</button>`:`<button class="rune-button secondary" disabled>${tier>1?'Clear Wind · Tier '+(tier-1):'Clear '+realms[Math.max(0,realm-1)]+' · Tier 1'}</button>`}</div></div>`;}
    function refresh(){const box=phone.querySelector('.location-context');if(!box)return;const sample=document.createElement('div');sample.innerHTML=locationView();const old=box.querySelector('.location-plaque');if(old){old.innerHTML=sample.firstElementChild.innerHTML;old.setAttribute('aria-label',sample.firstElementChild.getAttribute('aria-label'));}const bar=box.querySelector('.place-progress');if(bar){bar.setAttribute('aria-valuenow',J.cleared(data));bar.firstElementChild.style.width=J.cleared(data)/J.nodeCount*100+'%';}}
    function refreshAtlas(){if(!phone.querySelector('.tier-journey'))return;const next=document.createElement('div');next.innerHTML=view();for(const b of phone.querySelectorAll('[data-journey-node]')){const f=next.querySelector('[data-journey-node="'+b.dataset.journeyNode+'"]');b.className=f.className;b.disabled=f.disabled;b.innerHTML=f.innerHTML;if(f.hasAttribute('aria-current'))b.setAttribute('aria-current','location');else b.removeAttribute('aria-current');b.setAttribute('aria-label',f.getAttribute('aria-label'));}phone.querySelector('.journey-position').innerHTML=next.querySelector('.journey-position').innerHTML;const old=phone.querySelector('.journey-footer>button'),f=next.querySelector('.journey-footer>button');old.innerHTML=f.innerHTML;old.disabled=f.disabled;if(f.dataset.journeyPrimary)old.dataset.journeyPrimary=f.dataset.journeyPrimary;}
    function advanceIdle(){if(!state.connected||!J.clearIdle(data,state.seconds))return false;sync();return true;}
    function journeyAction(){if(atBoss())go('boss');else openModal({type:'map'});}
    function prepareFight(){const f=state.fight;f.journeyTarget=J.target(data);f.journeyTier=data.tier;f.journeyName=bossName();f.bossMax=Math.round(600*strength());f.bossHp=f.bossMax;}
    function finish(won,force=false){if(force&&state.view!=='fight'){if(!atBoss())return;startFight();}const f=state.fight;if(!f||f.result||!f.journeyTarget||won&&f.journeyTarget!==J.target(data))return;f.result=won?'win':'loss';if(won&&J.defeat(data,f.journeyTarget)){state.shards[f.realm]+=20;if(f.journeyTier===1&&f.realm===1&&complete())state.shards[0]+=20;f.journeyNext=J.next(data);sync();}go('result');}
    function bossView(){const ready=atBoss();return `<section class="page boss-prep"><div class="boss-summary">${sprite('golem')}<div><span class="kicker">${realms[data.realm]} · Tier ${data.tier} · Node ${nextBoss()}</span><h3>${bossName()}</h3><div class="compact-metrics">${metric('time','90s','Free attempt, 90 seconds')}${metric('power',Math.round(600*strength())+' HP','Boss health')}</div></div></div>${slots('boss',true)}<button class="familiar-summary" data-action="chooseFamiliar">${sprite(familiar(state.familiar).art)}<span><strong>${familiar(state.familiar).name}</strong><small>${familiar(state.familiar).buff} · Boss only</small></span>${glyph('edit')}</button>${ready?'':`<p class="compact-notice">${complete()?'All bosses cleared here':'Reach node '+nextBoss()+' to challenge this boss'}</p>`}<div class="primary-dock stack">${btn('Enter arena · Free retry','startFight',false,!ready||!state.boss.length)}${btn('Realm journey','map',true)}</div></section>`;}
    function resultView(){const f=state.fight,won=f.result==='win',next=f.journeyNext;return `<section class="page result-page center">${sprite(won?'portal':'moth','result-art')}${title(won?'Victory':'Try again')}<p class="muted">${f.journeyName}<br>${realms[f.realm]} · Tier ${f.journeyTier} · Node ${f.journeyTarget.split(':').at(-1)}</p>${won?`<div class="compact-metrics result-loot">${metric(realms[f.realm].toLowerCase(),'+20','Boss clear reward: 20 shards')}</div>${next?`<div class="next-realm-card">${ui(realms[next.realm].toLowerCase())}<strong>${realms[next.realm]} realm · Tier ${next.tier}</strong>${next.tier>f.journeyTier?`<span>${sprite('golem')} Stronger foes ${ui('empty')} New loot</span>`:'<span>New path · 25 nodes</span>'}</div>`:`<p class="note">Path opened · Node ${data.node}</p>`}`:'<p class="note">Progress kept · Free retry</p>'}<div class="primary-dock stack"><button class="rune-button" data-journey-continue>${won?(next?'Enter '+realms[next.realm]+' · Tier '+next.tier:'Continue farming'):'Prepare again'}</button>${won&&next?'<button class="text-button" data-journey-stay>Keep farming here</button>':''}</div></section>`;}
    function handle(el){
        if(!state.connected&&el.closest('#phone'))return false;
        if(el.closest('.progression-review-popover'))document.querySelector('.progression-review-popover')?.remove();
        if(el.dataset.journeyScenario){scenario(el.dataset.journeyScenario);return true;}
        if(el.hasAttribute('data-progression-reset')){scenario('route');return true;}
        if(el.hasAttribute('data-progression-advance')){advanceIdle();render(true);return true;}
        if(el.hasAttribute('data-journey-demo-win')){finish(true,true);return true;}
        if(el.dataset.journeyTier){state.modal.journeyTier=Number(el.dataset.journeyTier);render(true);return true;}
        if(el.dataset.journeyRealm!==undefined){state.modal.journeyRealm=Number(el.dataset.journeyRealm);render(true);return true;}
        if(el.dataset.journeyNode){const{tier,realm}=mapState(),n=Number(el.dataset.journeyNode);if(J.isBoss(n)){if(J.canVisit(data,tier,realm)&&n===J.cleared(data,tier,realm)+1&&J.travel(data,tier,realm,J.frontier(data,tier,realm))){sync();go('boss');}}else if(J.travel(data,tier,realm,n)){sync();go('realm');}return true;}
        if(el.dataset.journeyPrimary){const{tier,realm}=mapState();if(el.dataset.journeyPrimary==='boss')go('boss');else if(J.travel(data,tier,realm,J.frontier(data,tier,realm))){sync();go('realm');}return true;}
        if(el.hasAttribute('data-journey-continue')){const f=state.fight;if(f.result!=='win')go('boss');else{if(f.journeyNext){J.travel(data,f.journeyNext.tier,f.journeyNext.realm,1);sync();}go('realm');}return true;}
        if(el.hasAttribute('data-journey-stay')){go('realm');return true;}return false;
    }
    function change(delta){scenario(scenes[(scenes.indexOf(review)+delta+scenes.length)%scenes.length]);}
    function start(){if(!enabled())return;document.body.classList.add('realm-progression-study');const node=document.querySelector('#variant-label');node.setAttribute('role','button');node.tabIndex=0;node.setAttribute('aria-label','Öppna granskningskontroller');const toggle=()=>{const old=document.querySelector('.progression-review-popover');if(old){old.remove();return;}const pop=document.createElement('div');pop.className='progression-review-popover';pop.innerHTML='<span>GRANSKNING · ACCELERERAD SIMULERING</span><button data-progression-advance>Klara en idle-nod</button><button data-journey-demo-win>Visa bossvinst</button><button data-progression-reset>Återställ resan</button>';document.querySelector('.prototype-switcher').append(pop);};node.addEventListener('click',toggle);node.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle();}});document.querySelector('.prototype-switcher>span').textContent='A · VALD';scenario(new URLSearchParams(location.search).get('journey')||'route');}
    return {enabled,inspect,current,location:locationView,progress,view,refresh,refreshAtlas,advanceIdle,atBoss,enemyHp,journeyAction,prepareFight,finishFight:finish,bossView,resultView,handle,change,label:()=>labels[review],start,scenario};
})();
